	"insect-soldiers-of-the-sky": { image: 7019529, name: "Insect Soldiers of the Sky", nameFr: "Insectes Soldats Volants", kind: "monster", level: 3, atk: 1000, def: 800, attribute: "WIND", race: "Insect", frame: "effect", text: "If this card attacks a WIND monster, it gains 1000 ATK during the Damage Step only.", textFr: "À chaque fois que cette carte attaque un monstre VENT, augmentez l'ATK de cette carte de 1000 points uniquement durant la Damage Step." },
	"laser-cannon-armor": { image: 77007920, name: "Laser Cannon Armor", nameFr: "Armure Canon-Laser", kind: "spell", race: "Equip", frame: "spell", text: "Equip only to an Insect monster. It gains 300 ATK/DEF.", textFr: "Équipable uniquement à un monstre Insecte. Il gagne 300 ATK/DEF." },
