	"umi": { image: 22702055, name: "Umi", nameFr: "Umi", kind: "spell", race: "Field", frame: "spell", text: "All Fish, Sea Serpent, Thunder, and Aqua monsters on the field gain 200 ATK/DEF, also all Machine and Pyro monsters on the field lose 200 ATK/DEF.", textFr: "Tous les monstres Poisson/Serpent de Mer/Tonnerre/Aqua sur le Terrain gagnent 200 ATK/DEF, et aussi, tous les monstres Machine et Pyro sur le Terrain perdent 200 ATK/DEF." },
	"fortress-whale": { image: 62337487, name: "Fortress Whale", nameFr: "Baleine Forteresse", kind: "monster", level: 7, atk: 2350, def: 2150, attribute: "WATER", race: "Fish", frame: "ritual", text: "You can Ritual Summon this card with \"Fortress Whale's Oath\".", textFr: "Vous pouvez Invoquer Rituellement cette carte avec \"Serment de la Baleine Forteresse\"." },
	"fortress-whales-oath": { image: 77454922, name: "Fortress Whale's Oath", nameFr: "Serment de la Baleine Forteresse", kind: "spell", race: "Ritual", frame: "spell", text: "This card is used to Ritual Summon \"Fortress Whale\". You must also Tribute monsters from your hand or field whose total Levels equal 7 or more.", textFr: "Cette carte est utilisée pour Invoquer Rituellement \"Baleine Forteresse\". Vous devez aussi Sacrifier des monstres depuis votre main ou Terrain dont le Niveau total est égal à min. 7." },
